/**
 * The share cards' typefaces, embedded as base64 TrueType. Generated — do not edit.
 *
 * Embedded rather than fetched or read from disk: the cards render on a worker
 * where a network fetch is a dependency on a path that must never fail and
 * `fs` is not reliably there. Satori also cannot read WOFF2 or pick an
 * instance out of a variable font, so these are static instances, subset to
 * printable ASCII plus × · – — ‘ ’ “ ” … → (about 25KB each).
 *
 * To regenerate (fonttools):
 *   fonttools varLib.instancer "BricolageGrotesque[opsz,wdth,wght].ttf" wght=800 opsz=96 wdth=100 -o b800.ttf
 *   fonttools varLib.instancer "BricolageGrotesque[opsz,wdth,wght].ttf" wght=700 opsz=24 wdth=100 -o b700.ttf
 *   fonttools varLib.instancer "Inter[opsz,wght].ttf" wght=500 opsz=14 -o i500.ttf
 *   fonttools varLib.instancer "Inter[opsz,wght].ttf" wght=600 opsz=14 -o i600.ttf
 *   pyftsubset <each> --unicodes="U+0020-007E,U+00A0,U+00B7,U+00D7,U+2013,U+2014,U+2018,U+2019,U+201C,U+201D,U+2026,U+2192" \
 *     --layout-features="kern,liga,calt" --no-hinting --desubroutinize
 *
 * Both families are SIL Open Font License 1.1.
 */
